import type { CustomFont, FontsConfig } from "@templatical/types";
import {
  computed,
  getCurrentScope,
  onScopeDispose,
  ref,
  type ComputedRef,
  type Ref,
} from "vue";
import { logger } from "../utils/logger";

export interface FontOption {
  value: string;
  label: string;
  isCustom?: boolean;
}

export interface UseFontsReturn {
  fonts: ComputedRef<FontOption[]>;
  defaultFont: ComputedRef<string>;
  defaultFallback: ComputedRef<string>;
  customFonts: Ref<CustomFont[]>;
  customFontsEnabled: Ref<boolean>;
  isLoaded: Ref<boolean>;
  setCustomFontsEnabled: (enabled: boolean) => void;
  loadCustomFonts: () => Promise<void>;
  cleanupFontLinks: () => void;
  getFontWithFallback: (fontName: string) => string;
  getDefaultFont: () => string;
}

const BUILT_IN_FONTS: FontOption[] = [
  { value: "Arial", label: "Arial" },
  { value: "Helvetica", label: "Helvetica" },
  { value: "Georgia", label: "Georgia" },
  { value: "Times New Roman", label: "Times New Roman" },
  { value: "Verdana", label: "Verdana" },
  { value: "Trebuchet MS", label: "Trebuchet MS" },
  { value: "Courier New", label: "Courier New" },
];

const BUILT_IN_FONT_STACKS: Record<string, string> = {
  arial: "Arial, sans-serif",
  helvetica: "Helvetica, sans-serif",
  georgia: "Georgia, serif",
  "times new roman": "'Times New Roman', serif",
  verdana: "Verdana, sans-serif",
  "trebuchet ms": "'Trebuchet MS', sans-serif",
  "courier new": "'Courier New', monospace",
};

const DEFAULT_FALLBACK = "Arial, sans-serif";

/**
 * Resolve which built-in fonts the picker offers, honoring `FontsConfig.builtIns`:
 * `true`/`undefined` keeps all seven, `false` drops them all, and a `string[]`
 * keeps only the named families (case-insensitive, exact name). An entry that
 * isn't a built-in is warned and skipped (like an unknown `paletteBlocks` entry)
 * so a typo narrows the list instead of silently reinstating the full set. The
 * warning is emitted here rather than in a separate consumer: `useFonts` builds
 * its font list eagerly at init, so resolution and warning naturally live
 * together (unlike the palette, resolved lazily in `Sidebar`, which warns from a
 * watcher).
 *
 * Only the *picker* list is filtered; `BUILT_IN_FONT_STACKS` (fallback stacks)
 * and `isBuiltInFont` stay complete, so content already using an excluded family
 * still renders with its proper stack.
 */
function resolveBuiltInFonts(builtIns: FontsConfig["builtIns"]): FontOption[] {
  if (builtIns === undefined || builtIns === true) {
    return [...BUILT_IN_FONTS];
  }
  if (builtIns === false) {
    return [];
  }

  const allowed: FontOption[] = [];
  const seen = new Set<string>();
  const warned = new Set<string>();
  for (const name of builtIns) {
    const key = name.toLowerCase();
    const match = BUILT_IN_FONTS.find(
      (font) => font.value.toLowerCase() === key,
    );
    if (!match) {
      if (!warned.has(key)) {
        warned.add(key);
        logger.warn(
          `config.fonts.builtIns: "${name}" is not a built-in font — skipping it. ` +
            `Built-in fonts are: ${BUILT_IN_FONTS.map((font) => font.value).join(", ")}.`,
        );
      }
      continue;
    }
    if (seen.has(match.value)) continue;
    seen.add(match.value);
    allowed.push(match);
  }
  return allowed;
}

export function useFonts(config?: FontsConfig): UseFontsReturn {
  const customFonts = ref<CustomFont[]>(config?.customFonts ?? []);
  const customFontsEnabled = ref(true);
  const isLoaded = ref(false);

  // Built-in fonts the picker offers, after applying the `builtIns` allowlist.
  // Resolved once from config (not reactive): the allowlist can't change after
  // init, so an unknown-name warning fires exactly once per editor.
  const enabledBuiltInFonts = resolveBuiltInFonts(config?.builtIns);

  const defaultFallback = computed(
    () => config?.defaultFallback ?? DEFAULT_FALLBACK,
  );

  function setCustomFontsEnabled(enabled: boolean): void {
    customFontsEnabled.value = enabled;
  }

  const fonts = computed<FontOption[]>(() => {
    const builtInFonts = [...enabledBuiltInFonts];

    if (!customFontsEnabled.value) {
      return builtInFonts.sort((a, b) => a.label.localeCompare(b.label));
    }

    const customFontOptions: FontOption[] = customFonts.value.map((font) => ({
      value: font.name,
      label: font.name,
      isCustom: true,
    }));

    const allFonts = [...builtInFonts, ...customFontOptions];

    allFonts.sort((a, b) => a.label.localeCompare(b.label));

    return allFonts;
  });

  function isFontAvailable(fontName: string): boolean {
    return fonts.value.some(
      (font) =>
        font.label.toLowerCase() === fontName.toLowerCase() ||
        font.value.toLowerCase().startsWith(fontName.toLowerCase()),
    );
  }

  // Init-time check, same rationale as `resolveBuiltInFonts` above: `useFonts`
  // resolves everything eagerly at init, so a config-mismatch warning lives
  // here rather than in a separate consumer. A NEW template seeds
  // `config.defaultFont`, or the family from `DEFAULT_FALLBACK` when it's unset
  // (matching `createDefaultTemplateContent`'s "Arial" default). If the picker
  // doesn't offer that family — an excluded built-in, or no matching custom
  // font — authors land on a font they can't reselect, so warn once. Uses the
  // same case-insensitive family matching as `isBuiltInFont`, over the offered
  // list.
  const seededFontFamily =
    config?.defaultFont ?? DEFAULT_FALLBACK.split(",")[0].trim();
  if (!isFontAvailable(seededFontFamily)) {
    logger.warn(
      `config.fonts: new templates seed "${seededFontFamily}", which the font ` +
        `picker doesn't offer — authors can't reselect it. Either add it to ` +
        `fonts.builtIns, or set fonts.defaultFont to an offered font.`,
    );
  }

  function isBuiltInFont(fontName: string): boolean {
    return BUILT_IN_FONTS.some(
      (font) =>
        font.label.toLowerCase() === fontName.toLowerCase() ||
        font.value.toLowerCase().startsWith(fontName.toLowerCase()),
    );
  }

  function getDefaultFont(): string {
    if (config?.defaultFont) {
      if (!customFontsEnabled.value && !isBuiltInFont(config.defaultFont)) {
        return DEFAULT_FALLBACK;
      }

      if (isFontAvailable(config.defaultFont)) {
        const matchedFont = fonts.value.find(
          (font) =>
            font.label.toLowerCase() === config.defaultFont!.toLowerCase() ||
            font.value
              .toLowerCase()
              .startsWith(config.defaultFont!.toLowerCase()),
        );
        if (matchedFont) {
          return matchedFont.value;
        }
      }
    }
    return DEFAULT_FALLBACK;
  }

  const defaultFont = computed(() => getDefaultFont());

  function getFontWithFallback(fontName: string): string {
    if (!fontName) {
      return defaultFallback.value;
    }

    const customFont = customFonts.value.find(
      (font) => font.name.toLowerCase() === fontName.toLowerCase(),
    );

    if (customFont) {
      const fallback = customFont.fallback ?? defaultFallback.value;
      return `'${customFont.name}', ${fallback}`;
    }

    const builtInStack = BUILT_IN_FONT_STACKS[fontName.toLowerCase()];
    if (builtInStack) {
      return builtInStack;
    }

    return fontName.includes(",")
      ? fontName
      : `${fontName}, ${defaultFallback.value}`;
  }

  const createdLinks: HTMLLinkElement[] = [];
  let disposed = false;

  async function loadCustomFonts(): Promise<void> {
    if (customFonts.value.length === 0) {
      if (!disposed) isLoaded.value = true;
      return;
    }

    const loadPromises = customFonts.value.map(async (font) => {
      try {
        const existingLink = document.querySelector(
          `link[data-custom-font="${CSS.escape(font.name)}"]`,
        );
        if (existingLink) {
          return;
        }

        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = font.url;
        link.setAttribute("data-custom-font", font.name);

        // Track the link before awaiting so a load failure still leaves it
        // recoverable via cleanupFontLinks — otherwise the <link> orphans
        // in <head> after a network/CSS error.
        createdLinks.push(link);

        await new Promise<void>((resolve, reject) => {
          link.onload = () => resolve();
          link.onerror = () =>
            reject(new Error(`Failed to load font: ${font.name}`));
          // shadow-ok: web fonts must load at document level; @font-face from inside a shadow root is unreliable across browsers
          document.head.appendChild(link);
        });
      } catch (error) {
        logger.warn(`Failed to load custom font "${font.name}":`, error);
      }
    });

    await Promise.allSettled(loadPromises);
    if (disposed) return;
    isLoaded.value = true;
  }

  function cleanupFontLinks(): void {
    for (const link of createdLinks) {
      link.remove();
    }
    createdLinks.length = 0;
  }

  if (getCurrentScope()) {
    onScopeDispose(() => {
      disposed = true;
      cleanupFontLinks();
    });
  }

  return {
    fonts,
    defaultFont,
    defaultFallback,
    customFonts,
    customFontsEnabled,
    isLoaded,
    setCustomFontsEnabled,
    loadCustomFonts,
    cleanupFontLinks,
    getFontWithFallback,
    getDefaultFont,
  };
}
